```c
#include <stdio.h>
int main(void)
{
    int n = 10;
    do {
        printf("%d\n", n);
        n++;
    } while (n < 5);
    return 0;
}
```

What does this program print?

```c
#include <stdio.h>
int main(void)
{
    for (int i = 1; i <= 6; i++) {
        if (i % 2 == 0)
            continue;
        if (i == 5)
            break;
        printf("%d ", i);
